import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { AccessControlled } from "../governance/AccessControlled.sol";
import { IErrors } from "./interfaces/IErrors.sol";
import { ITranche } from "./interfaces/ITranche.sol";
import { IStrategy } from "./interfaces/IStrategy.sol";
import { IStrataCDO, IStrataCDOSetters } from "./interfaces/IStrataCDO.sol";
import { TActionState } from "./structs/TActionState.sol";
import { IAccounting } from "./interfaces/IAccounting.sol";

/// @notice Core CDO contract that orchestrates Tranches, Accounting, and Strategy
/// @dev Manages deposits, withdrawals, and asset distribution between tranches
contract StrataCDO is IErrors, IStrataCDO, IStrataCDOSetters, AccessControlled {

    /// @dev Accounting contract for managing asset flows and TVL redistribution
    /// @notice This contract handles the calculation of asset distribution between tranches based on target APRs
    /// @dev It's responsible for updating tranche balances, calculating risk-adjusted returns, and maintaining the reserve
    IAccounting public accounting;

    /// @dev The underlying investment strategy contract for this CDO
    /// @notice This contract implements the specific investment logic, e.g., USDe staking
    /// @dev Responsible for handling deposits, withdrawals, and calculating total assets
    /// @dev Interacts directly with external protocol to generate returns
    IStrategy public strategy;

    /// @notice Junior (BB) Tranche
    ITranche public jrtVault;

    /// @notice Senior (AA) Tranche
    ITranche public srtVault;

    /// @dev Address of the treasury wallet
    /// @dev Used as the recipient when reducing reserves
    /// @dev Can be updated by the RESERVE_MANAGER_ROLE
    address public treasury;

    /// @dev Controls the ability to deposit into or withdraw from the junior tranche
    TActionState public actionsJrt;

    /// @dev Controls the ability to deposit into or withdraw from the senior tranche
    TActionState public actionsSrt;

    /// @dev Configurable minimum JRT price per share, below which the protocol automatically pauses deposits
    uint256 public jrtShortfallPausePrice;

    /// @dev Withdrawal fees for the Junior Tranche
    uint256 public exitFeeJrt;

    /// @dev Withdrawal fees for the Senior Tranche
    uint256 public exitFeeSrt;

    event DepositsStateChanged(address indexed tranche, bool enabled);
    event WithdrawalsStateChanged(address indexed tranche, bool enabled);
    event ReserveReduced(address token, uint256 amount);
    event ReserveDistributed(uint256 jrtAmount, uint256 srtAmount);
    event TreasurySet(address treasury);
    event ShortfallPaused();
    event JrtShortfallPausePriceSet(uint256 pricePerShare);
    event ExitFeesSet(uint256 jrt, uint256 srt);

    /// @notice Restricts function access to only the junior (JRT) or senior (SRT) tranche contracts
    modifier onlyTranche() {
        if (msg.sender != address(jrtVault) && msg.sender != address(srtVault)) {
            revert InvalidCaller(msg.sender);
        }
        _;
    }

    function initialize(
        address owner_,
        address acm_
    ) public virtual initializer {
        AccessControlled_init(owner_, acm_);
        jrtShortfallPausePrice = 0.01e18;
    }

    /// @notice Calculates the total assets for a specific tranche
    /// @dev Retrieves the overall TVL from the strategy and determines the asset split
    /// @param tranche The address of the tranche (junior or senior) to return assets for
    /// @return The total assets allocated to the specified tranche
    /// @dev This function:
    ///      1. Gets the total TVL from the strategy
    ///      2. Uses the accounting contract to calculate the asset split
    ///      3. Returns the assets allocated to the specified tranche
    function totalAssets(address tranche) public view returns (uint256) {
        uint256 totalAssetsOverall = strategy.totalAssets();
        (uint256 jrtAssets, uint256 srtAssets, ) = accounting.totalAssets(
            totalAssetsOverall
        );
        if (isJrt(tranche)) {
            return jrtAssets;
        }
        return srtAssets;
    }

    /// @notice Returns the current total assets held in the strategy
    /// @dev This method retrieves the fresh amount of assets directly from the strategy contract
    /// @return uint256 The current total assets in the strategy
    function totalStrategyAssets() public view returns (uint256) {
        return strategy.totalAssets();
    }

    function pricePerShare(address tranche) public view returns (uint256) {
        uint256 assets = totalAssets(tranche);
        uint256 supply = ITranche(tranche).totalSupply();
        return calculatePricePerShare(assets, supply);
    }

    function maxDeposit(address tranche) external view returns (uint256) {
        bool isJrt_ = isJrt(tranche);
        bool isDepositEnabled = isJrt_ ? actionsJrt.isDepositEnabled : actionsSrt.isDepositEnabled;
        if (isDepositEnabled == false) {
            return 0;
        }
        return accounting.maxDeposit(isJrt_);
    }
    function maxWithdraw(address tranche) external view returns (uint256) {
        bool isJrt_ = isJrt(tranche);
        bool isWithdrawEnabled = isJrt_ ? actionsJrt.isWithdrawEnabled : actionsSrt.isWithdrawEnabled;
        if (isWithdrawEnabled == false) {
            return 0;
        }
        return accounting.maxWithdraw(isJrt_);
    }

    /// @notice Calculates the exit fee for a withdrawal from a specific tranche.
    /// @dev The calculation can be based on either the gross withdrawal amount (before fees)
    ///      or the net amount a user wishes to receive (after fees).
    /// @param tranche The address of the tranche (junior or senior).
    /// @param amount The amount to calculate the fee on.
    /// @param isGross If true, `amount` is the gross withdrawal amount.
    ///                If false, `amount` is the net amount to be received.
    /// @return The calculated exit fee amount.
    function calculateExitFee (address tranche, uint256 amount, bool isGross) external view returns (uint256) {
        uint256 fee = isJrt(tranche) ? exitFeeJrt : exitFeeSrt;
        return isGross
            ? Math.mulDiv(amount, fee, 1e18, Math.Rounding.Floor)
            : Math.mulDiv(amount, fee, 1e18 - fee, Math.Rounding.Floor);
    }

    /// @notice On behalf of a tranche, moves accrued fees from the tranche's TVL to the reserve.
    /// @param tranche The address of the tranche (JRT or SRT).
    /// @param assets The amount of fees to accrue.
    function accrueFee (address tranche, uint256 assets) external onlyTranche {
        accounting.accrueFee(isJrt(tranche), assets);
    }

    function updateAccounting () external onlyTranche {
        uint256 totalAssetsOverall = strategy.totalAssets();
        accounting.updateAccounting(totalAssetsOverall);
    }

    function deposit(address tranche, address token, uint256 tokenAmount, uint256 baseAssets) external onlyTranche nonReentrant {
        bool isJrt_ = isJrt(tranche);
        bool enabled = isJrt_ ? actionsJrt.isDepositEnabled : actionsSrt.isDepositEnabled;
        if (!enabled) {
            revert DepositsDisabled(tranche);
        }
        if (baseAssets > accounting.maxDeposit(isJrt_)) {
            revert DepositCapReached(tranche);
        }
        if (tokenAmount == 0 || baseAssets == 0) {
            revert ZeroAmount();
        }
        strategy.deposit(tranche, token, tokenAmount, baseAssets, /* owner: */ tranche);
        uint256 jrtAssetsIn = isJrt_ ? baseAssets : 0;
        uint256 srtAssetsIn = isJrt_ ? 0          : baseAssets;
        accounting.updateBalanceFlow(jrtAssetsIn, 0, srtAssetsIn, 0);
        shortfallPauser();
    }

    function withdraw(address tranche, address token, uint256 tokenAmount, uint256 baseAssets, address sender, address receiver) external onlyTranche nonReentrant {
        bool isJrt_ = isJrt(tranche);
        bool enabled = isJrt_ ? actionsJrt.isWithdrawEnabled : actionsSrt.isWithdrawEnabled;
        if (!enabled) {
            revert WithdrawalsDisabled(tranche);
        }
        if (baseAssets > accounting.maxWithdraw(isJrt_)) {
            revert WithdrawalCapReached(tranche);
        }
        if (tokenAmount == 0 || baseAssets == 0) {
            revert ZeroAmount();
        }
        strategy.withdraw(tranche, token, tokenAmount, baseAssets, sender, receiver);
        uint256 jrtAssetsOut = isJrt_ ? baseAssets : 0;
        uint256 srtAssetsOut = isJrt_ ? 0          : baseAssets;
        accounting.updateBalanceFlow(0, jrtAssetsOut, 0, srtAssetsOut);
        shortfallPauser();
    }

    /// @notice Determines if the given address is the Junior (BB) Tranche
    /// @dev Used to differentiate between Junior and Senior Tranches
    /// @param tranche The address to check
    /// @return bool True if the address is the Junior Tranche, false if it's the Senior Tranche
    /// @dev Reverts with InvalidTranche error if the address is neither Junior nor Senior Tranche
    function isJrt (address tranche) public view returns (bool) {
        if (tranche == address(jrtVault)) {
            return true;
        }
        if (tranche == address(srtVault)) {
            return false;
        }
        revert InvalidTranche(tranche);
    }

    /// @notice Configures the CDO with its components
    /// @dev Can only be called once by the owner after components deployment
    function configure (
        IAccounting accounting_,
        IStrategy strategy_,
        ITranche jrtVault_,
        ITranche srtVault_
    ) external onlyOwner {
        if (address(accounting) != address(0)) {
            revert AlreadyConfigured();
        }
        require(address(this) == accounting_.getCDOAddress(), "A1");
        require(address(this) ==   strategy_.getCDOAddress(), "A2");
        require(address(this) ==   jrtVault_.getCDOAddress(), "A3");
        require(address(this) ==   srtVault_.getCDOAddress(), "A4");

        accounting = accounting_;
        strategy = strategy_;
        jrtVault = jrtVault_;
        srtVault = srtVault_;

        jrtVault_.configure();
        srtVault_.configure();
    }

    /// @notice Reduces the reserve and transfers tokens to the treasury
    /// @dev Only callable by RESERVE_MANAGER_ROLE
    function reduceReserve (address token, uint256 tokenAmount) external onlyRole(RESERVE_MANAGER_ROLE) {
        if (treasury == address(0)) {
            revert ZeroAddress();
        }
        // Reverts if the token is not supported
        uint256 baseAssets = strategy.convertToAssets(token, tokenAmount, Math.Rounding.Floor);
        // Reverts if not enough reserve
        accounting.reduceReserve(baseAssets, 0, 0);
        // Transfers tokens out instantly if possible, or through the cooldown process
        strategy.reduceReserve(token, tokenAmount, treasury);
        emit ReserveReduced(token, tokenAmount);
    }

    /// @notice Reduces the reserve by distributing assets to the tranches
    /// @dev Only callable by RESERVE_MANAGER_ROLE
    function distributeReserve (uint256 jrtAmountIn, uint256 srtAmountIn) external onlyRole(RESERVE_MANAGER_ROLE) {
        // The accounting contract reverts if reserves are insufficient.
        accounting.reduceReserve(jrtAmountIn + srtAmountIn, jrtAmountIn, srtAmountIn);
        emit ReserveDistributed(jrtAmountIn, srtAmountIn);
    }

    /// @notice Sets the address of the reserve treasury
    function setReserveTreasury (address treasury_) external onlyRole(RESERVE_MANAGER_ROLE) {
        treasury = treasury_;
        emit TreasurySet(treasury_);
    }

    /// @notice Sets action states for the tranche; zero address affects both tranches
    function setActionStates (address tranche, bool isDepositEnabled, bool isWithdrawEnabled) external onlyRole(PAUSER_ROLE) {
        if (address(tranche) == address(0)) {
            setActionStatesInner(address(jrtVault), isDepositEnabled, isWithdrawEnabled);
            setActionStatesInner(address(srtVault), isDepositEnabled, isWithdrawEnabled);
            return;
        }
        setActionStatesInner(tranche, isDepositEnabled, isWithdrawEnabled);
    }

    /// @notice Internal function to set deposit and withdrawal states for a tranche
    function setActionStatesInner (address tranche, bool isDepositEnabled, bool isWithdrawEnabled) internal {
        TActionState storage state = isJrt(tranche)? actionsJrt : actionsSrt;
        if (state.isDepositEnabled != isDepositEnabled) {
            state.isDepositEnabled = isDepositEnabled;
            emit DepositsStateChanged(tranche, isDepositEnabled);
        }
        if (state.isWithdrawEnabled != isWithdrawEnabled) {
            state.isWithdrawEnabled = isWithdrawEnabled;
            emit WithdrawalsStateChanged(tranche, isWithdrawEnabled);
        }
    }

    /// @notice Sets the exit fees for the junior and senior tranches.
    /// @dev This method is only callable by the TwoStepConfigManager. Please see {twoStepConfigManager} for more details.
    function setExitFees (uint256 feeJrt, uint256 feeSrt) external onlyTwoStepConfigManager {
        require(feeJrt <= 0.01e18, "InvalidJrtFee");
        require(feeSrt <= 0.01e18, "InvalidSrtFee");
        exitFeeJrt = feeJrt;
        exitFeeSrt = feeSrt;
        emit ExitFeesSet(feeJrt, feeSrt);
    }

    /// @notice Sets the JRT shortfall price to automatically pause the deposits, when the price falls below this price
    function setJrtShortfallPausePrice (uint256 jrtShortfallPausePrice_) external onlyRole(PAUSER_ROLE) {
        // If the shortfall pause price is above current price, deposits must be paused manually by the Pauser
        require(jrtShortfallPausePrice_ <= pricePerShare(address(jrtVault)), "ShortfallPriceTooLarge");
        jrtShortfallPausePrice = jrtShortfallPausePrice_;
        emit JrtShortfallPausePriceSet(jrtShortfallPausePrice_);
    }

    function shortfallPauser () internal {
        (uint256 jrtNav,,) = accounting.totalAssetsT0();
        uint256 jrtPrice = calculatePricePerShare(jrtNav, jrtVault.totalSupply());
        if (jrtPrice <= jrtShortfallPausePrice) {
            actionsJrt.isDepositEnabled = false;
            actionsSrt.isDepositEnabled = false;
            emit DepositsStateChanged(address(jrtVault), false);
            emit DepositsStateChanged(address(srtVault), false);
            emit ShortfallPaused();
        }
    }

    function calculatePricePerShare (uint256 assets, uint256 supply) internal pure returns (uint256) {
        return supply == 0
            ? 1e18
            : Math.mulDiv(assets, 1e18, supply, Math.Rounding.Floor);
    }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC4626 } from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IErrors } from "../../interfaces/IErrors.sol";
import { IStrataCDO } from "../../interfaces/IStrataCDO.sol";
import { IERC20Cooldown, IUnstakeCooldown } from "../../interfaces/cooldown/ICooldown.sol";
import { Strategy } from "../../Strategy.sol";

contract sUSDeStrategy is Strategy {

    IERC4626 public immutable sUSDe;
    IERC20 public immutable USDe;

    IERC20Cooldown public erc20Cooldown;
    IUnstakeCooldown public unstakeCooldown;

    /** configuration */

    uint256 public sUSDeCooldownJrt;
    uint256 public sUSDeCooldownSrt;

    event CooldownsChanged(uint256 jrt, uint256 srt);

    constructor (IERC4626 sUSDe_) {
        sUSDe = sUSDe_;
        USDe = IERC20(sUSDe_.asset());
    }

    function initialize(
        address owner_,
        address acm_,
        IStrataCDO cdo_,
        IERC20Cooldown erc20Cooldown_,
        IUnstakeCooldown unstakeCooldown_
    ) public virtual initializer {
        AccessControlled_init(owner_, acm_);

        cdo = cdo_;
        erc20Cooldown = erc20Cooldown_;
        unstakeCooldown = unstakeCooldown_;

        SafeERC20.forceApprove(sUSDe, address(erc20Cooldown), type(uint256).max);
        SafeERC20.forceApprove(sUSDe, address(unstakeCooldown), type(uint256).max);
    }

    /**
     * @notice Processes asset deposits for the CDO contract.
     * @dev This method is called by the CDO contract to handle asset deposits.
     *      If the deposited token is USDe, it will be staked to receive sUSDe.
     *      If the deposited token is already sUSDe, it will be accepted as is.
     * @param tranche The address of the tranche depositing assets (not used in this strategy)
     * @param token The address of the token being deposited
     * @param tokenAmount The amount of tokens being deposited
     * @param baseAssets The amount of base assets represented by the deposit (used for sUSDe deposits)
     * @param owner The address of the asset owner from whom to transfer tokens
     * @return The amount of base assets received after deposit
     */
    function deposit (address tranche, address token, uint256 tokenAmount, uint256 baseAssets, address owner) external onlyCDO returns (uint256) {
        SafeERC20.safeTransferFrom(IERC20(token), owner, address(this), tokenAmount);

        if (token == address(USDe)) {
            SafeERC20.forceApprove(USDe, address(sUSDe), tokenAmount);
            sUSDe.deposit(tokenAmount, address(this));
            return tokenAmount;
        }
        if (token == address(sUSDe)) {
            // already transferred in ↑
            return baseAssets;
        }
        revert UnsupportedToken(token);
    }

    /**
     * @notice Processes asset withdrawals for the CDO contract.
     * @dev This method is called by the CDO contract to handle asset withdrawals.
     *      If withdrawing sUSDe, a cooldown period is applied based on the tranche type.
     *      If withdrawing USDe, the sUSDe is unstaked with a cooldown.
     * @param tranche The address of the tranche withdrawing assets
     * @param token The address of the token to be withdrawn
     * @param tokenAmount The amount of tokens to be withdrawn (not used in this implementation)
     * @param baseAssets The amount of base assets to be withdrawn
     * @param receiver The address that will receive the withdrawn assets
     * @param sender The account that initiated the withdrawal
     * @return The amount of tokens withdrawn (shares for sUSDe, baseAssets for USDe)
     */
    function withdraw (address tranche, address token, uint256 tokenAmount, uint256 baseAssets, address sender, address receiver) external onlyCDO returns (uint256) {
        uint256 shares = sUSDe.previewWithdraw(baseAssets);
        if (token == address(sUSDe)) {
            uint256 cooldownSeconds = cdo.isJrt (tranche) ? sUSDeCooldownJrt : sUSDeCooldownSrt;
            erc20Cooldown.transfer(sUSDe, sender, receiver, shares, cooldownSeconds);
            return shares;
        }
        if (token == address(USDe)) {
            unstakeCooldown.transfer(sUSDe, sender, receiver, shares);
            return baseAssets;
        }
        revert UnsupportedToken(token);
    }

    /**
     * @notice Allows the CDO to withdraw tokens from the strategy's reserve
     * @dev This function is part of the reserve reduction process and can only be called by the CDO.
     *      It handles both sUSDe and USDe tokens, applying different transfer mechanisms for each.
     *      For sUSDe, it uses erc20Cooldown with no cooldown period.
     *      For USDe, it uses unstakeCooldown to handle the unstaking process.
     * @param token The address of the token to be withdrawn (either sUSDe or USDe)
     * @param tokenAmount The amount of tokens to be withdrawn
     * @param receiver The address that will receive the withdrawn tokens
     */
    function reduceReserve (address token, uint256 tokenAmount, address receiver) external onlyCDO {
        if (token == address(sUSDe)) {
            erc20Cooldown.transfer(sUSDe, receiver, receiver, tokenAmount, 0);
            return;
        }
        if (token == address(USDe)) {
            // tokenAmount is in USDe, convert to sUSDe shares (Rounding.Floor/in favor of protocol) and trigger unstaking
            uint256 shares = sUSDe.convertToShares(tokenAmount);
            if (shares == 0) {
                revert ZeroAmount();
            }
            unstakeCooldown.transfer(sUSDe, receiver, receiver, shares);
            return;
        }
        revert UnsupportedToken(token);
    }

    /**
     * @notice Calculates the total assets managed by this strategy
     * @dev This function returns the current value of the strategy's assets in USDe.
     * @return baseAssets The total amount of USDe managed by this strategy
     */
    function totalAssets () external view returns (uint256 baseAssets) {
        uint256 shares = sUSDe.balanceOf(address(this));
        baseAssets = sUSDe.previewRedeem(shares);
        return baseAssets;
    }

    /**
     * @notice Converts a given amount of supported tokens to their equivalent in USDe
     * @dev This function handles conversion for both sUSDe and USDe tokens.
     *      For sUSDe, it uses the vault's exchange rate, considering the rounding direction.
     *      For USDe, it returns the input amount as is.
     * @param token The address of the token to convert (either sUSDe or USDe)
     * @param tokenAmount The amount of tokens to convert
     * @param rounding The rounding direction to use for the conversion (floor or ceiling)
     * @return The equivalent amount in USDe
     */
    function convertToAssets (address token, uint256 tokenAmount, Math.Rounding rounding) external view returns (uint256) {
        if (token == address(sUSDe)) {
            return rounding == Math.Rounding.Floor
                ? sUSDe.previewRedeem(tokenAmount) // aka convertToAssets(tokenAmount)
                : sUSDe.previewMint(tokenAmount);
        }
        if (token == address(USDe)) {
            return tokenAmount;
        }
        revert UnsupportedToken(token);
    }

    /**
     * @notice Converts a given amount of base assets (USDe) to the equivalent amount of supported tokens
     * @dev This function handles conversion for both sUSDe and USDe tokens.
     *      For sUSDe, it uses the vault's exchange rate, considering the rounding direction.
     *      For USDe, it returns the input amount as is.
     * @param token The address of the token to convert to (either sUSDe or USDe)
     * @param baseAssets The amount of base assets (USDe) to convert
     * @param rounding The rounding direction to use for the conversion (floor or ceiling)
     * @return The equivalent amount in the requested token (sUSDe shares or USDe)
     */
    function convertToTokens (address token, uint256 baseAssets, Math.Rounding rounding) external view returns (uint256) {
        if (token == address(sUSDe)) {
            return rounding == Math.Rounding.Floor
                ? sUSDe.previewDeposit(baseAssets) // aka convertToShares(baseAssets)
                : sUSDe.previewWithdraw(baseAssets);
        }
        if (token == address(USDe)) {
            return baseAssets;
        }
        revert UnsupportedToken(token);
    }

     /**
     * @notice Returns an array of supported tokens: sUSDe and USDe
     */
    function getSupportedTokens () external view returns (IERC20[] memory) {
        IERC20[] memory tokens = new IERC20[](2);
        tokens[0] = IERC20(address(sUSDe));
        tokens[1] = USDe;
        return tokens;
    }

     /**
     * @notice Updates the cooldown periods for sUSDe withdrawals (USDe cooldown is already defined by Ethena's unstaking period)
     */
    function setCooldowns (uint256 sUSDeCooldownJrt_, uint256 sUSDeCooldownSrt_) external onlyRole(UPDATER_STRAT_CONFIG_ROLE) {
        uint256 WEEK = 7 days;
        if (sUSDeCooldownJrt_ > WEEK || sUSDeCooldownSrt_ > WEEK) {
            revert InvalidConfigCooldown();
        }
        sUSDeCooldownJrt = sUSDeCooldownJrt_;
        sUSDeCooldownSrt = sUSDeCooldownSrt_;

        bool isDisabled = sUSDeCooldownJrt_ == 0 && sUSDeCooldownSrt_ == 0;
        erc20Cooldown.setCooldownDisabled(sUSDe, isDisabled);
        emit CooldownsChanged(sUSDeCooldownJrt_, sUSDeCooldownSrt_);
    }
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Clones } from "@openzeppelin/contracts/proxy/Clones.sol";
import { IUnstakeHandler } from "../../interfaces/cooldown/IUnstakeHandler.sol";
import { IUnstakeCooldown } from "../../interfaces/cooldown/ICooldown.sol";
import { CooldownBase } from "./CooldownBase.sol";

/**
 * @title Strata Unstake Cooldown Manager
 */
contract UnstakeCooldown is IUnstakeCooldown, CooldownBase {

    event UserProxyCreated(address indexed user, address proxy);
    event UserProxyImplementationSet(address token, address impl);

    struct TRequest {
        uint64 unlockAt;
        IUnstakeHandler proxy;
    }

    /// @dev Unstaking implementations for each supported token and protocol
    mapping(address token => IUnstakeHandler unstakeImpl) public implementations;

    /// @dev Active requests
    mapping(address token => mapping(address account => TRequest[] requests)) public activeRequests;

    /// @dev Maintain proxies Pool, after the request is completed, the proxy is returned to the pool
    mapping(address token => mapping(address account => IUnstakeHandler[] proxy)) public proxiesPool;

    /// @notice Transfers assets from msg.sender (Strategy) to the specified user by creating an unstake request in the underlying protocol
    /// @dev After the cooldown period elapses in the underlying protocol,
    /// @dev the requests can be finalized and the funds are unlocked and transferred to the user
    /// @param token The ERC20 token being transferred
    /// @param initialFrom The original sender of the assets, specified by the strategy
    /// @param to The recipient of the unstaked assets
    /// @param amount The amount of tokens to transfer
    /// @custom:access Restricted to COOLDOWN_WORKER_ROLE
    function transfer(IERC20 token, address initialFrom, address to, uint256 amount) external onlyRole(COOLDOWN_WORKER_ROLE) {
        address worker = msg.sender;
        if (amount == 0) {
            return;
        }
        address impl = address(implementations[address(token)]);
        if (impl == address(0)) {
            revert UnsupportedToken(address(token));
        }

        TRequest[] storage requests = activeRequests[address(token)][to];
        IUnstakeHandler[] storage proxies = proxiesPool[address(token)][to];

        IUnstakeHandler proxy;
        bool shouldReuseRequest = false;
        uint256 requestsCount = requests.length;
        if (initialFrom != to && requestsCount >= PUBLIC_REQUEST_SLOTS_CAP) {
            revert ExternalReceiverRequestLimitReached(token, initialFrom, to, amount);
        }
        if (requestsCount > 0) {
            // Check if we should create a new request or extend the last one
            shouldReuseRequest = requestsCount >= MAX_ACTIVE_REQUEST_SLOTS
                || requests[requestsCount - 1].proxy.requestedAt() == block.timestamp;
        }
        if (shouldReuseRequest) {
            proxy = requests[requestsCount - 1].proxy;
        } else {
            uint256 len = proxies.length;
            if (len > 0) {
                proxy = IUnstakeHandler(proxies[len - 1]);
                proxies.pop();
                if (impl != getImplementation(address(proxy))) {
                    proxy = createFor(impl, to);
                }
            } else {
                proxy = createFor(impl, to);
            }
        }

        SafeERC20.safeTransferFrom(token, worker, address(proxy), amount);

        uint256 unlockAt = proxy.request();
        emit TransferRequested(token, initialFrom, to, amount, unlockAt);

        if (shouldReuseRequest) {
            if (unlockAt > block.timestamp) {
                // If not an instant transfer, update the existing unlockAt
                requests[requestsCount - 1].unlockAt = uint64(unlockAt);
            }
            // exit, do not modify requests and proxies
            return;
        }
        if (unlockAt <= block.timestamp) {
            // already transferred (instant transfer), return proxy to pool and exit
            proxies.push(proxy);
            emit Finalized(token, to, amount);
            return;
        }
        requests.push(TRequest(uint64(unlockAt), proxy));
    }

    /// @notice Finalizes the requests up to the current block timestamp
    /// @custom:see finalize(IERC20 token, address user, uint256 at) for more detailed documentation
    function finalize(IERC20 token, address user) external returns (uint256 claimed) {
        return finalize(token, user, block.timestamp);
    }

    /// @notice Finalizes unstake requests for a user, processing all eligible requests up to the specified timestamp
    /// @param token The ERC20 token being unstaked
    /// @param user The address of the user whose requests are being finalized
    /// @param at The timestamp up to which requests should be processed
    /// @return claimed The total amount of tokens claimed from finalized requests
    function finalize(IERC20 token, address user, uint256 at) public returns (uint256 claimed) {
        if (at > block.timestamp) {
            revert InvalidTime();
        }
        TRequest[] storage requests = activeRequests[address(token)][user];
        IUnstakeHandler[] storage proxies = proxiesPool[address(token)][user];
        IUnstakeHandler imp = implementations[address(token)];

        // Emergency exit: check the underlying protocol if the cooldown is still active
        bool isCooldownActive = imp.isCooldownActive();
        uint256 len = requests.length;
        for (uint256 i; i < len; ) {
            TRequest memory req = requests[i];
            if (isCooldownActive && req.unlockAt > at) {
                // Still pending
                unchecked { i++; }
                continue;
            }

            claimed += req.proxy.finalize();
            // Return proxy to the pool (reuse later)
            proxies.push(req.proxy);

            if (i < len - 1) {
                requests[i] = requests[len - 1];
            }
            requests.pop();
            unchecked { len--; }
        }
        if (claimed == 0) {
            revert NothingToFinalize();
        }

        emit Finalized(token, user, claimed);
        return claimed;
    }

    /// @notice Returns the user's balance state at the current block timestamp
    /// @custom:see balanceOf(IERC20 token, address user, uint256 at) for more detailed documentation
    function balanceOf (IERC20 token, address user) external view returns (TBalanceState memory) {
        return balanceOf(token, user, block.timestamp);
    }

    /// @notice Returns the user's balance state for a given unstakable token at a specific timestamp
    /// @dev Balance includes pending and claimable amounts in underlying tokens
    /// @param token The unstakable token address
    /// @param user The user's address
    /// @param at The timestamp for which to calculate the balance
    /// @return TBalanceState struct containing pending, claimable, and next unlock details in underlying tokens
    function balanceOf (IERC20 token, address user, uint256 at) public view returns (TBalanceState memory) {
        TRequest[] storage requests = activeRequests[address(token)][user];
        IUnstakeHandler imp = implementations[address(token)];
        bool isCooldownActive = imp.isCooldownActive();

        uint256 l = requests.length;

        uint256 pending;
        uint256 claimable;
        uint256 nextUnlockAt;
        uint256 nextUnlockAmount;

        for (uint256 i; i < l; i++) {
            TRequest memory req = requests[i];
            uint256 amount = req.proxy.getPendingAmount();
            if (isCooldownActive && req.unlockAt > at) {
                pending += amount;
                if (nextUnlockAt == 0 || req.unlockAt < nextUnlockAt) {
                    nextUnlockAt = req.unlockAt;
                    nextUnlockAmount = amount;
                    continue;
                }
                if (req.unlockAt == nextUnlockAt) {
                    nextUnlockAmount += amount;
                }
                continue;
            }
            claimable += amount;
        }
        return TBalanceState({
            pending: pending,
            claimable: claimable,
            nextUnlockAt: nextUnlockAt,
            nextUnlockAmount: nextUnlockAmount,
            totalRequests: l
        });
    }

    function createFor(address implementation, address user) internal returns (IUnstakeHandler proxy) {
        proxy = IUnstakeHandler(Clones.clone(implementation, 0));
        proxy.initialize(address(this), user);
        emit UserProxyCreated(user, address(proxy));
        return proxy;
    }

    /**
     * @dev Updates the implementations for tokens. Implementation can be ZERO address in case we want to remove supported token.
     */
    function setImplementations(address[] calldata tokens_, IUnstakeHandler[] calldata implementations_) external onlyOwner {
        uint256 len = tokens_.length;
        for (uint256 i = 0; i < len; ) {
            address token = tokens_[i];
            IUnstakeHandler impl = implementations_[i];
            implementations[token] = impl;
            emit UserProxyImplementationSet(token, address(impl));
            unchecked { i++; }
        }
    }

    function getImplementation(address proxy) internal view returns (address implementation) {
        assembly {
            // Clones.clone := 0x363d3d373d3d3d363d73<20-byte implementation>5af43d82803e903d91602b57fd5bf3
            let ptr := mload(0x40)
            extcodecopy(proxy, ptr, 10, 32)
            implementation := shr(96, mload(ptr)) // right-shift to 20 bytes
        }
    }
}

